  1	package br.com.marealta;
  2	
  3	import java.math.BigDecimal;
  4	import java.sql.SQLException;
  5	import java.time.LocalDate;
  6	import java.time.YearMonth;
  7	import java.util.List;
  8	
  9	final class Service {
 10	    private final Db db;
 11	
 12	    Service(Db db) { this.db = db; }
 13	
 14	    record NewReservation(int roomNumber, String guestName, String guestEmail, Identification identification,
 15	                          LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
 16	
 17	    record IssuedDocument(Reservation reservation, Room room, Documents.Document document) {}
 18	
 19	    private static final BigDecimal ZERO = Money.round(BigDecimal.ZERO);
 20	
 21	    List<Room> rooms() {
 22	        return db.tx(Repository::rooms);
 23	    }
 24	
 25	    List<Message> messages() {
 26	        return db.tx(Repository::messages);
 27	    }
 28	
 29	    Reservation create(NewReservation n) {
 30	        return db.tx(c -> {
 31	            // o lock da linha do quarto serializa reservas concorrentes do mesmo quarto
 32	            Room room = Repository.room(c, n.roomNumber(), true).orElseThrow(
 33	                    () -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + n.roomNumber() + " não existe"));
 34	            if (n.guests() > room.capacity()) {
 35	                throw new ApiException(422, "CAPACITY_EXCEEDED",
 36	                        "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
 37	            }
 38	            if (Repository.hasOverlap(c, room.number(), n.checkIn(), n.checkOut())) {
 39	                throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
 40	            }
 41	            Pricing.Quote q = Pricing.quote(room.nightlyRate(), n.checkIn(), n.checkOut(), n.ratePlan());
 42	            Reservation draft = new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.identification(),
 43	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), q.nights(), q.subtotal(), q.discount(),
 44	                    q.total(), Status.PENDING, ZERO, null);
 45	            long id = Repository.insert(c, draft);
 46	            return Repository.reservation(c, id, false).orElseThrow();
 47	        });
 48	    }
 49	
 50	    Reservation get(long id) {
 51	        return db.tx(c -> load(c, id, false));
 52	    }
 53	
 54	    Reservation confirm(long id) {
 55	        return db.tx(c -> {
 56	            Reservation r = load(c, id, true);
 57	            requireStatus(r, "confirmar", Status.PENDING);
 58	            Repository.updateState(c, id, Status.CONFIRMED, r.total(), null);
 59	            Reservation confirmed = load(c, id, false);
 60	            Room room = Repository.room(c, r.roomNumber(), false).orElseThrow();
 61	            Documents.Document doc = Documents.render(confirmed, room);
 62	            Repository.insertMessage(c, "EMAIL", confirmed.guestEmail(), Documents.confirmationSubject(),
 63	                    Documents.confirmationBody(confirmed, doc));
 64	            return confirmed;
 65	        });
 66	    }
 67	
 68	    Reservation cancel(long id) {
 69	        return db.tx(c -> {
 70	            Reservation r = load(c, id, true);
 71	            requireStatus(r, "cancelar", Status.PENDING, Status.CONFIRMED);
 72	            BigDecimal refund = r.status() == Status.CONFIRMED && r.ratePlan() == RatePlan.STANDARD
 73	                    ? r.amountPaid() : ZERO;
 74	            Repository.updateState(c, id, Status.CANCELLED, r.amountPaid(), refund);
 75	            return load(c, id, false);
 76	        });
 77	    }
 78	
 79	    Reservation checkIn(long id) {
 80	        return db.tx(c -> {
 81	            Reservation r = load(c, id, true);
 82	            requireStatus(r, "fazer check-in de", Status.CONFIRMED);
 83	            Repository.updateState(c, id, Status.CHECKED_IN, r.amountPaid(), r.refund());
 84	            return load(c, id, false);
 85	        });
 86	    }
 87	
 88	    IssuedDocument checkOut(long id) {
 89	        return db.tx(c -> {
 90	            Reservation r = load(c, id, true);
 91	            requireStatus(r, "fazer check-out de", Status.CHECKED_IN);
 92	            Repository.updateState(c, id, Status.CHECKED_OUT, r.amountPaid(), r.refund());
 93	            return issue(c, load(c, id, false));
 94	        });
 95	    }
 96	
 97	    /** Segunda via: só para reserva paga. */
 98	    IssuedDocument document(long id) {
 99	        return db.tx(c -> {
100	            Reservation r = load(c, id, false);
101	            if (!r.status().isPaid()) {
102	                throw ApiException.notAllowed("Só existe documento para reserva paga; a reserva está " + r.status());
103	            }
104	            return issue(c, r);
105	        });
106	    }
107	
108	    String occupancyReport(LocalDate night) {
109	        return db.tx(c -> {
110	            List<Reservation> rows = Repository.reservations(c, """
111	                    WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND check_in <= ? AND check_out > ?
112	                    ORDER BY room_number, id""", night, night);
113	            List<Room> rooms = Repository.rooms(c);
114	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
115	            for (Reservation r : rows) {
116	                Room room = rooms.stream().filter(x -> x.number() == r.roomNumber()).findFirst().orElseThrow();
117	                csv.append(r.roomNumber()).append(',').append(room.type()).append(',').append(r.id()).append(',')
118	                        .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
119	            }
120	            long occupied = rows.stream().map(Reservation::roomNumber).distinct().count();
121	            csv.append("total,").append(occupied).append('/').append(rooms.size()).append('\n');
122	            return csv.toString();
123	        });
124	    }
125	
126	    String revenueReport(YearMonth month) {
127	        return db.tx(c -> {
128	            List<Reservation> rows = Repository.reservations(c, """
129	                    WHERE check_in >= ? AND check_in <= ? AND amount_paid - COALESCE(refund, 0) > 0
130	                    ORDER BY check_in, id""", month.atDay(1), month.atEndOfMonth());
131	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
132	            BigDecimal sum = ZERO;
133	            for (Reservation r : rows) {
134	                BigDecimal kept = r.amountPaid().subtract(r.refund() == null ? ZERO : r.refund());
135	                sum = sum.add(kept);
136	                csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
137	                        .append(r.checkOut()).append(',').append(r.status()).append(',').append(kept).append('\n');
138	            }
139	            csv.append("total,").append(sum).append('\n');
140	            return csv.toString();
141	        });
142	    }
143	
144	    private static Reservation load(java.sql.Connection c, long id, boolean lock) throws SQLException {
145	        return Repository.reservation(c, id, lock).orElseThrow(
146	                () -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe"));
147	    }
148	
149	    private static IssuedDocument issue(java.sql.Connection c, Reservation r) throws SQLException {
150	        Room room = Repository.room(c, r.roomNumber(), false).orElseThrow();
151	        return new IssuedDocument(r, room, Documents.render(r, room));
152	    }
153	
154	    private static void requireStatus(Reservation r, String action, Status... allowed) {
155	        for (Status s : allowed) if (r.status() == s) return;
156	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva com status " + r.status());
157	    }
158	}
  1	package br.com.marealta;
  2	
  3	import java.sql.Connection;
  4	import java.sql.PreparedStatement;
  5	import java.sql.ResultSet;
  6	import java.sql.SQLException;
  7	import java.sql.Statement;
  8	import java.time.LocalDate;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	import java.util.Optional;
 12	
 13	/** Acesso SQL; todos os métodos usam a conexão (transação) de quem chama. */
 14	final class Repository {
 15	    private Repository() {}
 16	
 17	    private static final String RES_COLS = """
 18	        id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
 19	        guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
 20	        subtotal, discount, total, status, amount_paid, refund""";
 21	
 22	    static List<Room> rooms(Connection c) throws SQLException {
 23	        try (PreparedStatement ps = c.prepareStatement(
 24	                "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
 25	             ResultSet rs = ps.executeQuery()) {
 26	            List<Room> out = new ArrayList<>();
 27	            while (rs.next()) out.add(room(rs));
 28	            return out;
 29	        }
 30	    }
 31	
 32	    static Optional<Room> room(Connection c, int number, boolean lock) throws SQLException {
 33	        try (PreparedStatement ps = c.prepareStatement(
 34	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?" + (lock ? " FOR UPDATE" : ""))) {
 35	            ps.setInt(1, number);
 36	            try (ResultSet rs = ps.executeQuery()) {
 37	                return rs.next() ? Optional.of(room(rs)) : Optional.empty();
 38	            }
 39	        }
 40	    }
 41	
 42	    private static Room room(ResultSet rs) throws SQLException {
 43	        return new Room(rs.getInt("number"), RoomType.valueOf(rs.getString("type")),
 44	                rs.getInt("capacity"), rs.getBigDecimal("nightly_rate"));
 45	    }
 46	
 47	    static boolean hasOverlap(Connection c, int room, LocalDate in, LocalDate out) throws SQLException {
 48	        try (PreparedStatement ps = c.prepareStatement("""
 49	                SELECT 1 FROM reservations
 50	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ? LIMIT 1""")) {
 51	            ps.setInt(1, room);
 52	            ps.setObject(2, out);
 53	            ps.setObject(3, in);
 54	            try (ResultSet rs = ps.executeQuery()) {
 55	                return rs.next();
 56	            }
 57	        }
 58	    }
 59	
 60	    static long insert(Connection c, Reservation r) throws SQLException {
 61	        try (PreparedStatement ps = c.prepareStatement("""
 62	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
 63	                  guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
 64	                  subtotal, discount, total, status, amount_paid, refund)
 65	                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
 66	            int i = 1;
 67	            ps.setInt(i++, r.roomNumber());
 68	            ps.setString(i++, r.guestName());
 69	            ps.setString(i++, r.guestEmail());
 70	            String cpf = null, cnpj = null, company = null, passport = null, country = null;
 71	            switch (r.identification()) {
 72	                case Identification.Cpf id -> cpf = id.cpf();
 73	                case Identification.Company id -> { cnpj = id.cnpj(); company = id.companyName(); }
 74	                case Identification.Passport id -> { passport = id.passport(); country = id.country(); }
 75	            }
 76	            ps.setString(i++, cpf);
 77	            ps.setString(i++, cnpj);
 78	            ps.setString(i++, company);
 79	            ps.setString(i++, passport);
 80	            ps.setString(i++, country);
 81	            ps.setObject(i++, r.checkIn());
 82	            ps.setObject(i++, r.checkOut());
 83	            ps.setInt(i++, r.guests());
 84	            ps.setString(i++, r.ratePlan().name());
 85	            ps.setInt(i++, r.nights());
 86	            ps.setBigDecimal(i++, r.subtotal());
 87	            ps.setBigDecimal(i++, r.discount());
 88	            ps.setBigDecimal(i++, r.total());
 89	            ps.setString(i++, r.status().name());
 90	            ps.setBigDecimal(i++, r.amountPaid());
 91	            ps.setBigDecimal(i, r.refund());
 92	            ps.executeUpdate();
 93	            try (ResultSet keys = ps.getGeneratedKeys()) {
 94	                keys.next();
 95	                return keys.getLong(1);
 96	            }
 97	        }
 98	    }
 99	
100	    static Optional<Reservation> reservation(Connection c, long id, boolean lock) throws SQLException {
101	        try (PreparedStatement ps = c.prepareStatement(
102	                "SELECT " + RES_COLS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
103	            ps.setLong(1, id);
104	            try (ResultSet rs = ps.executeQuery()) {
105	                return rs.next() ? Optional.of(reservation(rs)) : Optional.empty();
106	            }
107	        }
108	    }
109	
110	    /** Reservas que atendem a condição SQL (já com ORDER BY), com os parâmetros dados. */
111	    static List<Reservation> reservations(Connection c, String whereAndOrder, Object... params) throws SQLException {
112	        try (PreparedStatement ps = c.prepareStatement("SELECT " + RES_COLS + " FROM reservations " + whereAndOrder)) {
113	            for (int i = 0; i < params.length; i++) ps.setObject(i + 1, params[i]);
114	            try (ResultSet rs = ps.executeQuery()) {
115	                List<Reservation> out = new ArrayList<>();
116	                while (rs.next()) out.add(reservation(rs));
117	                return out;
118	            }
119	        }
120	    }
121	
122	    private static Reservation reservation(ResultSet rs) throws SQLException {
123	        Identification id;
124	        if (rs.getString("guest_cpf") != null) {
125	            id = new Identification.Cpf(rs.getString("guest_cpf"));
126	        } else if (rs.getString("company_cnpj") != null) {
127	            id = new Identification.Company(rs.getString("company_cnpj"), rs.getString("company_name"));
128	        } else {
129	            id = new Identification.Passport(rs.getString("guest_passport"), rs.getString("guest_country"));
130	        }
131	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
132	                rs.getString("guest_email"), id,
133	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
134	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), rs.getInt("nights"),
135	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
136	                Status.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
137	    }
138	
139	    static void updateState(Connection c, long id, Status status, java.math.BigDecimal amountPaid,
140	                            java.math.BigDecimal refund) throws SQLException {
141	        try (PreparedStatement ps = c.prepareStatement(
142	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
143	            ps.setString(1, status.name());
144	            ps.setBigDecimal(2, amountPaid);
145	            ps.setBigDecimal(3, refund);
146	            ps.setLong(4, id);
147	            ps.executeUpdate();
148	        }
149	    }
150	
151	    static void insertMessage(Connection c, String channel, String to, String subject, String body) throws SQLException {
152	        try (PreparedStatement ps = c.prepareStatement(
153	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
154	            ps.setString(1, channel);
155	            ps.setString(2, to);
156	            ps.setString(3, subject);
157	            ps.setString(4, body);
158	            ps.executeUpdate();
159	        }
160	    }
161	
162	    static List<Message> messages(Connection c) throws SQLException {
163	        try (PreparedStatement ps = c.prepareStatement(
164	                "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
165	             ResultSet rs = ps.executeQuery()) {
166	            List<Message> out = new ArrayList<>();
167	            while (rs.next()) {
168	                out.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4), rs.getString(5)));
169	            }
170	            return out;
171	        }
172	    }
173	}

