  1	package br.com.marealta;
  2	
  3	import com.fasterxml.jackson.core.JsonProcessingException;
  4	import com.fasterxml.jackson.databind.JsonNode;
  5	import com.fasterxml.jackson.databind.ObjectMapper;
  6	import io.javalin.Javalin;
  7	import io.javalin.http.Context;
  8	
  9	import java.io.IOException;
 10	import java.time.LocalDate;
 11	import java.time.YearMonth;
 12	import java.time.format.DateTimeParseException;
 13	import java.util.LinkedHashMap;
 14	
 15	import java.util.Map;
 16	
 17	final class Api {
 18	    private static final ObjectMapper JSON = new ObjectMapper();
 19	
 20	    private final Service service;
 21	
 22	    Api(Service service) { this.service = service; }
 23	
 24	    Javalin create() {
 25	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 26	
 27	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 28	        app.exception(Exception.class, (e, ctx) -> {
 29	            e.printStackTrace();
 30	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 31	        });
 32	
 33	        app.get("/rooms", ctx -> json(ctx, 200, service.rooms().stream().map(Api::roomJson).toList()));
 34	        app.post("/reservations", ctx -> json(ctx, 201, reservationJson(service.create(parseNew(ctx)))));
 35	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationJson(service.get(id(ctx)))));
 36	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservationJson(service.confirm(id(ctx)))));
 37	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservationJson(service.cancel(id(ctx)))));
 38	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservationJson(service.checkIn(id(ctx)))));
 39	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, documentJson(service.checkOut(id(ctx)))));
 40	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, documentJson(service.document(id(ctx)))));
 41	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(Api::messageJson).toList()));
 42	
 43	        app.get("/reports/occupancy", ctx -> {
 44	            String raw = ctx.queryParam("date");
 45	            if (raw == null) throw ApiException.invalid("Parâmetro date é obrigatório (AAAA-MM-DD)");
 46	            csv(ctx, service.occupancyReport(parseDate(raw, "date")));
 47	        });
 48	        app.get("/reports/revenue", ctx -> {
 49	            String raw = ctx.queryParam("month");
 50	            if (raw == null) throw ApiException.invalid("Parâmetro month é obrigatório (AAAA-MM)");
 51	            YearMonth month;
 52	            try {
 53	                month = YearMonth.parse(raw);
 54	            } catch (DateTimeParseException e) {
 55	                throw ApiException.invalid("month inválido, use AAAA-MM");
 56	            }
 57	            csv(ctx, service.revenueReport(month));
 58	        });
 59	        return app;
 60	    }
 61	
 62	    // ---------- entrada ----------
 63	
 64	    private static long id(Context ctx) {
 65	        try {
 66	            return Long.parseLong(ctx.pathParam("id"));
 67	        } catch (NumberFormatException e) {
 68	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não existe");
 69	        }
 70	    }
 71	
 72	    private static Service.NewReservation parseNew(Context ctx) {
 73	        JsonNode body;
 74	        try {
 75	            body = JSON.readTree(ctx.bodyAsBytes());
 76	        } catch (IOException e) {
 77	            throw ApiException.invalid("Corpo da requisição não é um JSON válido");
 78	        }
 79	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo da requisição deve ser um objeto JSON");
 80	
 81	        int roomNumber = requiredInt(body, "roomNumber");
 82	        String name = requiredText(body, "guestName");
 83	        String email = requiredText(body, "guestEmail");
 84	        LocalDate checkIn = parseDate(requiredText(body, "checkIn"), "checkIn");
 85	        LocalDate checkOut = parseDate(requiredText(body, "checkOut"), "checkOut");
 86	        int guests = requiredInt(body, "guests");
 87	        RatePlan plan;
 88	        try {
 89	            plan = RatePlan.valueOf(requiredText(body, "ratePlan"));
 90	        } catch (IllegalArgumentException e) {
 91	            throw ApiException.invalid("ratePlan inválido: use STANDARD ou NON_REFUNDABLE");
 92	        }
 93	        Identification identification = parseIdentification(body);
 94	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("checkOut deve ser depois de checkIn");
 95	        if (guests < 1) throw ApiException.invalid("guests deve ser pelo menos 1");
 96	        return new Service.NewReservation(roomNumber, name, email, identification, checkIn, checkOut, guests, plan);
 97	    }
 98	
 99	    /** Exatamente um: CPF; CNPJ + razão social; ou passaporte + país. */
100	    private static Identification parseIdentification(JsonNode body) {
101	        String cpf = optionalText(body, "guestCpf");
102	        String cnpj = optionalText(body, "companyCnpj");
103	        String company = optionalText(body, "companyName");
104	        String passport = optionalText(body, "guestPassport");
105	        String country = optionalText(body, "guestCountry");
106	
107	        boolean isCpf = cpf != null;
108	        boolean isCompany = cnpj != null || company != null;
109	        boolean isPassport = passport != null || country != null;
110	        if ((isCpf ? 1 : 0) + (isCompany ? 1 : 0) + (isPassport ? 1 : 0) != 1) {
111	            throw ApiException.invalid("Informe guestCpf, ou companyCnpj com companyName, ou guestPassport com guestCountry");
112	        }
113	        if (isCpf) return new Identification.Cpf(cpf);
114	        if (isCompany) {
115	            if (cnpj == null || company == null) throw ApiException.invalid("companyCnpj e companyName devem vir juntos");
116	            return new Identification.Company(cnpj, company);
117	        }
118	        if (passport == null || country == null) throw ApiException.invalid("guestPassport e guestCountry devem vir juntos");
119	        return new Identification.Passport(passport, country);
120	    }
121	
122	    private static String requiredText(JsonNode body, String field) {
123	        String v = optionalText(body, field);
124	        if (v == null) throw ApiException.invalid("Campo obrigatório ausente ou vazio: " + field);
125	        return v;
126	    }
127	
128	    /** Ausente, null ou em branco = null; outro tipo que não texto é inválido. */
129	    private static String optionalText(JsonNode body, String field) {
130	        JsonNode n = body.get(field);
131	        if (n == null || n.isNull()) return null;
132	        if (!n.isTextual()) throw ApiException.invalid("Campo " + field + " deve ser texto");
133	        return n.asText().isBlank() ? null : n.asText();
134	    }
135	
136	    private static int requiredInt(JsonNode body, String field) {
137	        JsonNode n = body.get(field);
138	        if (n == null || n.isNull()) throw ApiException.invalid("Campo obrigatório ausente: " + field);
139	        if (!n.isIntegralNumber() || !n.canConvertToInt()) throw ApiException.invalid("Campo " + field + " deve ser um inteiro");
140	        return n.intValue();
141	    }
142	
143	    private static LocalDate parseDate(String raw, String field) {
144	        try {
145	            return LocalDate.parse(raw);
146	        } catch (DateTimeParseException e) {
147	            throw ApiException.invalid(field + " inválida, use AAAA-MM-DD");
148	        }
149	    }
150	
151	    // ---------- saída ----------
152	
153	    private static void json(Context ctx, int status, Object body) {
154	        try {
155	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
156	        } catch (JsonProcessingException e) {
157	            throw new IllegalStateException(e);
158	        }
159	    }
160	
161	    private static void csv(Context ctx, String body) {
162	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));
163	    }
164	
165	    private static void error(Context ctx, int status, String code, String message) {
166	        Map<String, Object> m = new LinkedHashMap<>();
167	        m.put("error", code);
168	        m.put("message", message);
169	        json(ctx, status, m);
170	    }
171	
172	    private static Map<String, Object> roomJson(Room r) {
173	        Map<String, Object> m = new LinkedHashMap<>();
174	        m.put("number", r.number());
175	        m.put("type", r.type());
176	        m.put("capacity", r.capacity());
177	        m.put("nightlyRate", r.nightlyRate());
178	        return m;
179	    }
180	
181	    private static Map<String, Object> messageJson(Message msg) {
182	        Map<String, Object> m = new LinkedHashMap<>();
183	        m.put("id", msg.id());
184	        m.put("channel", msg.channel());
185	        m.put("to", msg.to());
186	        m.put("subject", msg.subject());
187	        m.put("body", msg.body());
188	        return m;
189	    }
190	
191	    /** Os cinco campos de identificação; os que não se aplicam vão null. */
192	    private static void putIdentification(Map<String, Object> m, Identification id) {
193	        m.put("guestCpf", id instanceof Identification.Cpf c ? c.cpf() : null);
194	        m.put("companyCnpj", id instanceof Identification.Company c ? c.cnpj() : null);
195	        m.put("companyName", id instanceof Identification.Company c ? c.companyName() : null);
196	        m.put("guestPassport", id instanceof Identification.Passport p ? p.passport() : null);
197	        m.put("guestCountry", id instanceof Identification.Passport p ? p.country() : null);
198	    }
199	
200	    private static Map<String, Object> reservationJson(Reservation r) {
201	        Map<String, Object> m = new LinkedHashMap<>();
202	        m.put("id", r.id());
203	        m.put("roomNumber", r.roomNumber());
204	        m.put("guestName", r.guestName());
205	        m.put("guestEmail", r.guestEmail());
206	        putIdentification(m, r.identification());
207	        m.put("checkIn", r.checkIn().toString());
208	        m.put("checkOut", r.checkOut().toString());
209	        m.put("guests", r.guests());
210	        m.put("ratePlan", r.ratePlan());
211	        m.put("nights", r.nights());
212	        m.put("subtotal", r.subtotal());
213	        m.put("discount", r.discount());
214	        m.put("total", r.total());
215	        m.put("status", r.status());
216	        m.put("amountPaid", r.amountPaid());
217	        m.put("refund", r.refund());
218	        return m;
219	    }
220	
221	    private static Map<String, Object> documentJson(Service.IssuedDocument d) {
222	        Reservation r = d.reservation();
223	        Map<String, Object> m = new LinkedHashMap<>();
224	        m.put("title", d.document().title());
225	        m.put("reservationId", r.id());
226	        m.put("guestName", r.guestName());
227	        putIdentification(m, r.identification());
228	        m.put("roomNumber", d.room().number());
229	        m.put("roomType", d.room().type());
230	        m.put("checkIn", r.checkIn().toString());
231	        m.put("checkOut", r.checkOut().toString());
232	        m.put("nights", r.nights());
233	        m.put("subtotal", r.subtotal());
234	        m.put("discount", r.discount());
235	        m.put("total", r.total());
236	        m.put("text", d.document().text());
237	        return m;
238	    }
239	}
