 17	final class Api {
 18	    private static final ObjectMapper JSON = new ObjectMapper();
 19	
 20	    private final Service service;
 21	
 22	    Api(Service service) { this.service = service; }
 23	
 24	    Javalin create() {
 25	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 26	
 27	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 28	        app.exception(Exception.class, (e, ctx) -> {
 29	            e.printStackTrace();
 30	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 31	        });
 32	
 33	        app.get("/rooms", ctx -> json(ctx, 200, service.rooms().stream().map(Api::roomJson).toList()));
 34	        app.post("/reservations", ctx -> json(ctx, 201, reservationJson(service.create(parseNew(ctx)))));
 35	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationJson(service.get(id(ctx)))));
 36	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservationJson(service.confirm(id(ctx)))));
 37	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservationJson(service.cancel(id(ctx)))));
 38	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservationJson(service.checkIn(id(ctx)))));
 39	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, documentJson(service.checkOut(id(ctx)))));
 40	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, documentJson(service.document(id(ctx)))));
 41	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(Api::messageJson).toList()));
 42	
 43	        app.get("/reports/occupancy", ctx -> {
 44	            String raw = ctx.queryParam("date");
 45	            if (raw == null) throw ApiException.invalid("Parâmetro date é obrigatório (AAAA-MM-DD)");
 46	            csv(ctx, service.occupancyReport(parseDate(raw, "date")));
 47	        });
 48	        app.get("/reports/revenue", ctx -> {
 49	            String raw = ctx.queryParam("month");
 50	            if (raw == null) throw ApiException.invalid("Parâmetro month é obrigatório (AAAA-MM)");
 51	            YearMonth month;
 52	            try {
 53	                month = YearMonth.parse(raw);
 54	            } catch (DateTimeParseException e) {
 55	                throw ApiException.invalid("month inválido, use AAAA-MM");
 56	            }
 57	            csv(ctx, service.revenueReport(month));
 58	        });
 59	        return app;
 60	    }
